"""Recursive-descent parser for MiniDB's SQL subset.

Consumes the token list produced by ``minidb.tokenizer.tokenize`` (which
always ends with an EOF token) and builds the frozen AST nodes defined in
``minidb.types``. The statement and WHERE-expression grammars are
documented in the ``minidb.types`` module docstring:

* Precedence NOT > AND > OR; AND/OR are left-associative.
* Comparisons do not chain (``a = b = c`` is an error).
* ``IS [NOT] NULL`` produces ``IsNull(operand, negated)``.
* INSERT values must be literals, converted to Values: INTEGER token ->
  ``int``, STRING -> ``str``, TRUE/FALSE -> ``bool``, NULL -> ``None``.
* Column types in CREATE TABLE are the keywords INTEGER, TEXT, BOOLEAN,
mapped to ``ColumnType``.

Any malformed input raises ``SQLSyntaxError``.
"""

from __future__ import annotations

from minidb.types import (
    COMPARISON_OPS,
    And,
    ColumnDef,
    ColumnRef,
    ColumnType,
    Comparison,
    CreateTableStmt,
    DeleteStmt,
    DropTableStmt,
    Expr,
    InsertStmt,
    IsNull,
    Literal,
    Not,
    Or,
    SelectStmt,
    SQLSyntaxError,
    Statement,
    Token,
    TokenType,
    Value,
)

__all__ = ["parse", "parse_script", "parse_expression"]


def parse(tokens: list[Token]) -> Statement:
    """Parse exactly one statement, optionally followed by a single ';',
    then EOF.

    Raises:
        SQLSyntaxError: if the tokens are not exactly one valid statement
            (including empty input, a lone ';', or trailing tokens).
    """
    def consume(token_type: TokenType) -> Token:
        if tokens and tokens[0].type == token_type:
            return tokens.pop(0)
        raise SQLSyntaxError(f"Expected {token_type}, got {tokens[0].type}")

    def consume_optional(token_type: TokenType) -> Token | None:
        if tokens and tokens[0].type == token_type:
            return tokens.pop(0)
        return None

    def parse_create_table() -> CreateTableStmt:
        consume(TokenType.KEYWORD)  # CREATE
        consume(TokenType.KEYWORD)  # TABLE
        table_name = consume(TokenType.IDENTIFIER).value
        consume(TokenType.OPERATOR)  # (
        columns = []
        while tokens[0].type != TokenType.OPERATOR or tokens[0].value != ")":
            col_name = consume(TokenType.IDENTIFIER).value
            col_type = consume(TokenType.KEYWORD).value
            if col_type == "INTEGER":
                columns.append(ColumnDef(col_name, ColumnType.INTEGER))
            elif col_type == "TEXT":
                columns.append(ColumnDef(col_name, ColumnType.TEXT))
            elif col_type == "BOOLEAN":
                columns.append(ColumnDef(col_name, ColumnType.BOOLEAN))
            else:
                raise SQLSyntaxError(f"Unknown column type: {col_type}")
            if tokens[0].type == TokenType.OPERATOR and tokens[0].value == ",":
                consume(TokenType.OPERATOR)  # ,
        consume(TokenType.OPERATOR)  # )
        return CreateTableStmt(table_name, tuple(columns))

    def parse_drop_table() -> DropTableStmt:
        consume(TokenType.KEYWORD)  # DROP
        consume(TokenType.KEYWORD)  # TABLE
        table_name = consume(TokenType.IDENTIFIER).value
        return DropTableStmt(table_name)

    def parse_insert_stmt() -> InsertStmt:
        consume(TokenType.KEYWORD)  # INSERT
        consume(TokenType.KEYWORD)  # INTO
        table_name = consume(TokenType.IDENTIFIER).value
        columns = None
        if tokens[0].type == TokenType.OPERATOR and tokens[0].value == "(":
            consume(TokenType.OPERATOR)  # (
            columns = []
            while tokens[0].type != TokenType.OPERATOR or tokens[0].value != ")":
                columns.append(consume(TokenType.IDENTIFIER).value)
                if tokens[0].type == TokenType.OPERATOR and tokens[0].value == ",":
                    consume(TokenType.OPERATOR)  # ,
            consume(TokenType.OPERATOR)  # )
        consume(TokenType.KEYWORD)  # VALUES
        consume(TokenType.OPERATOR)  # (
        values = []
        while tokens[0].type != TokenType.OPERATOR or tokens[0].value != ")":
            token = consume(tokens[0].type)
            if token.type == TokenType.INTEGER:
                values.append(int(token.value))
            elif token.type == TokenType.STRING:
                values.append(token.value)
            elif token.type == TokenType.KEYWORD and token.value == "TRUE":
                values.append(True)
            elif token.type == TokenType.KEYWORD and token.value == "FALSE":
                values.append(False)
            elif token.type == TokenType.KEYWORD and token.value == "NULL":
                values.append(None)
            else:
                raise SQLSyntaxError(f"Unexpected token: {token}")
            if tokens[0].type == TokenType.OPERATOR and tokens[0].value == ",":
                consume(TokenType.OPERATOR)  # ,
        consume(TokenType.OPERATOR)  # )
        return InsertStmt(table_name, tuple(columns) if columns else None, tuple(values))

    def parse_select_stmt() -> SelectStmt:
        consume(TokenType.KEYWORD)  # SELECT
        columns = None
        if tokens[0].type == TokenType.OPERATOR and tokens[0].value == "*":
            consume(TokenType.OPERATOR)  # *
        else:
            columns = []
            while tokens[0].type != TokenType.KEYWORD or tokens[0].value != "FROM":
                columns.append(consume(TokenType.IDENTIFIER).value)
                if tokens[0].type == TokenType.OPERATOR and tokens[0].value == ",":
                    consume(TokenType.OPERATOR)  # ,
            columns = tuple(columns)
        consume(TokenType.KEYWORD)  # FROM
        table_name = consume(TokenType.IDENTIFIER).value
        where = None
        if tokens and tokens[0].type == TokenType.KEYWORD and tokens[0].value == "WHERE":
            consume(TokenType.KEYWORD)  # WHERE
            where = parse_expression(tokens)
        return SelectStmt(table_name, columns, where)

    def parse_delete_stmt() -> DeleteStmt:
        consume(TokenType.KEYWORD)  # DELETE
        consume(TokenType.KEYWORD)  # FROM
        table_name = consume(TokenType.IDENTIFIER).value
        where = None
        if tokens and tokens[0].type == TokenType.KEYWORD and tokens[0].value == "WHERE":
            consume(TokenType.KEYWORD)  # WHERE
            where = parse_expression(tokens)
        return DeleteStmt(table_name, where)

    if not tokens:
        raise SQLSyntaxError("Unexpected EOF")

    stmt = None
    if tokens[0].type == TokenType.KEYWORD and tokens[0].value == "CREATE":
        stmt = parse_create_table()
    elif tokens[0].type == TokenType.KEYWORD and tokens[0].value == "DROP":
        stmt = parse_drop_table()
    elif tokens[0].type == TokenType.KEYWORD and tokens[0].value == "INSERT":
        stmt = parse_insert_stmt()
    elif tokens[0].type == TokenType.KEYWORD and tokens[0].value == "SELECT":
        stmt = parse_select_stmt()
    elif tokens[0].type == TokenType.KEYWORD and tokens[0].value == "DELETE":
        stmt = parse_delete_stmt()
    else:
        raise SQLSyntaxError(f"Unexpected token: {tokens[0]}")

    consume_optional(TokenType.OPERATOR)  # ;
    consume(TokenType.EOF)
    return stmt


def parse_script(tokens: list[Token]) -> list[Statement]:
    """Parse zero or more ';'-separated statements up to EOF.

    Empty statements (consecutive ';' or a trailing ';') are skipped; an
    empty token stream (just EOF) yields ``[]``.

    Raises:
        SQLSyntaxError: if any statement is malformed.
    """
    statements = []
    while tokens and tokens[0].type != TokenType.EOF:
        try:
            stmt = parse(tokens)
            if not isinstance(stmt, (DropTableStmt, InsertStmt, SelectStmt, DeleteStmt)):
                raise SQLSyntaxError(f"Unexpected statement: {stmt}")
            statements.append(stmt)
        except SQLSyntaxError:
            if tokens[0].type == TokenType.OPERATOR and tokens[0].value == ";":
                consume_optional(TokenType.OPERATOR)  # ;
            else:
                raise
    consume(TokenType.EOF)
    return statements


def parse_expression(tokens: list[Token]) -> Expr:
    """Parse a single WHERE-style expression that must consume every token
    up to EOF.

    Raises:
        SQLSyntaxError: if the tokens do not form exactly one expression.
    """
    def consume(token_type: TokenType) -> Token:
        if tokens and tokens[0].type == token_type:
            return tokens.pop(0)
        raise SQLSyntaxError(f"Expected {token_type}, got {tokens[0].type}")

    def parse_primary() -> Expr:
        if tokens[0].type == TokenType.OPERATOR and tokens[0].value == "(":
            consume(TokenType.OPERATOR)  # (
            expr = parse_or_expr()
            consume(TokenType.OPERATOR)  # )
            return expr
        elif tokens[0].type == TokenType.IDENTIFIER:
            return ColumnRef(consume(TokenType.IDENTIFIER).value)
        elif tokens[0].type in (TokenType.INTEGER, TokenType.STRING):
            token = consume(tokens[0].type)
            if token.type == TokenType.INTEGER:
                return Literal(int(token.value))
            elif token.type == TokenType.STRING:
                return Literal(token.value)
        elif tokens[0].type == TokenType.KEYWORD and tokens[0].value == "TRUE":
            consume(TokenType.KEYWORD)
            return Literal(True)
        elif tokens[0].type == TokenType.KEYWORD and tokens[0].value == "FALSE":
            consume(TokenType.KEYWORD)
            return Literal(False)
        elif tokens[0].type == TokenType.KEYWORD and tokens[0].value == "NULL":
            consume(TokenType.KEYWORD)
            return Literal(None)
        else:
            raise SQLSyntaxError(f"Unexpected token: {tokens[0]}")

    def parse_is_null() -> IsNull:
        operand = parse_primary()
        consume(TokenType.KEYWORD)  # IS
        negated = False
        if tokens[0].type == TokenType.KEYWORD and tokens[0].value == "NOT":
            consume(TokenType.KEYWORD)  # NOT
            negated = True
        consume(TokenType.KEYWORD)  # NULL
        return IsNull(operand, negated)

    def parse_predicate() -> Expr:
        if tokens[0].type == TokenType.KEYWORD and tokens[0].value == "IS":
            return parse_is_null()
        left = parse_primary()
        if tokens[0].type == TokenType.OPERATOR and tokens[0].value in COMPARISON_OPS:
            op = consume(TokenType.OPERATOR).value
            right = parse_primary()
            return Comparison(op, left, right)
        return left

    def parse_not_expr() -> Expr:
        if tokens[0].type == TokenType.KEYWORD and tokens[0].value == "NOT":
            consume(TokenType.KEYWORD)  # NOT
            return Not(parse_not_expr())
        return parse_predicate()

    def parse_and_expr() -> Expr:
        expr = parse_not_expr()
        while tokens and tokens[0].type == TokenType.KEYWORD and tokens[0].value == "AND":
            consume(TokenType.KEYWORD)  # AND
            expr = And(expr, parse_not_expr())
        return expr

    def parse_or_expr() -> Expr:
        expr = parse_and_expr()
        while tokens and tokens[0].type == TokenType.KEYWORD and tokens[0].value == "OR":
            consume(TokenType.KEYWORD)  # OR
            expr = Or(expr, parse_and_expr())
        return expr

    if not tokens:
        raise SQLSyntaxError("Unexpected EOF")

    expr = parse_or_expr()
    consume(TokenType.EOF)
    return expr

